import sqlite3
import uuid
from typing import Optional

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI(
    title="NeighborhoodAlertBoard",
    description="Allows users to submit and retrieve neighborhood alerts.",
    version="1.0.0",
)

DATABASE_URL = "db.sqlite3"


class AlertBase(BaseModel):
    title: str
    description: str


class AlertCreate(AlertBase):
    latitude: Optional[float] = None
    longitude: Optional[float] = None


class Alert(AlertBase):
    id: str
    city: str


def get_db_connection():
    conn = sqlite3.connect(DATABASE_URL)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db_connection() as conn:
        cursor = conn.cursor()
        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS alerts (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                description TEXT NOT NULL,
                city TEXT NOT NULL
            );
            """
        )
        conn.commit()


@app.on_event("startup")
async def startup_event():
    init_db()


def get_city_from_coordinates(latitude: Optional[float], longitude: Optional[float]) -> str:
    # This is a placeholder for a real geocoding service.
    # For the purpose of this exercise, we'll return a static city or a generic one.
    if latitude is not None and longitude is not None:
        if 37.7749 <= latitude <= 37.7750 and -122.4195 <= longitude <= -122.4193:
            return "San Francisco"
        elif 34.0522 <= latitude <= 34.0523 and -118.2437 <= longitude <= -118.2436:
            return "Los Angeles"
        else:
            return "Unknown City"
    return "N/A"


# Override the default validation error handler to return 400 instead of 422
@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"detail": exc.errors()},
    )


@app.post(
    "/alerts",
    response_model=Alert,
    status_code=status.HTTP_201_CREATED,
    summary="Submit a new neighborhood alert",
    responses={
        201: {"description": "Alert successfully created"},
        400: {"description": "Invalid input (e.g., missing required fields or malformed data)"},
        422: {"description": "Unprocessable entity (e.g., invalid coordinate format)"},
    },
)
async def create_alert(alert: AlertCreate):
    alert_id = str(uuid.uuid4())
    city = get_city_from_coordinates(alert.latitude, alert.longitude)

    with get_db_connection() as conn:
        cursor = conn.cursor()
        try:
            cursor.execute(
                "INSERT INTO alerts (id, title, description, city) VALUES (?, ?, ?, ?)",
                (alert_id, alert.title, alert.description, city),
            )
            conn.commit()
        except sqlite3.Error as e:
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Database error: {e}"
            )

    return Alert(id=alert_id, title=alert.title, description=alert.description, city=city)


@app.get(
    "/alerts/{alertId}",
    response_model=Alert,
    summary="Retrieve a stored alert by ID",
    responses={
        200: {"description": "The requested alert"},
        404: {"description": "Alert not found"},
        400: {"description": "Malformed alert ID"},
    },
)
async def get_alert(alertId: str):
    if not alertId:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Malformed alert ID")

    with get_db_connection() as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT id, title, description, city FROM alerts WHERE id = ?", (alertId,))
        alert_data = cursor.fetchone()

    if alert_data is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Alert not found")

    return Alert(**alert_data)


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=5000)
